//! Golden-file tests for the WGSL generated by [`crate::shader`].
//!
//! Each shader below is compiled at build time and its complete WGSL module is
//! compared with a checked-in file under `tests/golden/`. Regenerate the files
//! after an intentional change with:
//!
//! ```text
//! UPDATE_GOLDEN=1 cargo test -p sequoia-shader --lib golden
//! ```
//!
//! The goldens make standard-library and ABI changes reviewable: any edit to
//! `wgsl/std.wgsl`, the prelude, or the macro's codegen shows up as a diff.

#[allow(unused_imports)]
use crate::{Color, FragUv, Sampler2D, SequoiShader, Vec3, shader};

shader! {
    pub fn solid(color: Color, gain: f32, invert: bool) -> Color {
        return vec4<f32>(color.rgb * gain, select(color.a, 1.0 - color.a, invert));
    }
}

shader! {
    pub fn gradient(uv: FragUv, from_color: Color, to_color: Color) -> Color {
        let t = uv.x;
        return vec4<f32>(sq_mix3(from_color.rgb, to_color.rgb, t), 1.0);
    }
}

shader! {
    pub fn hue_shift(uv: FragUv, amount: f32) -> Color {
        let hsv = sq_rgb_to_hsv(vec3<f32>(uv.x, uv.y, 0.5));
        let shifted = sq_hsv_to_rgb(vec3<f32>(fract(hsv.x + amount), hsv.y, hsv.z));
        return vec4<f32>(shifted, 1.0);
    }
}

shader! {
    pub fn luminance(uv: FragUv) -> Color {
        let v = sq_luminance(vec3<f32>(uv.x, uv.y, 0.5));
        return vec4<f32>(v, v, v, 1.0);
    }
}

shader! {
    pub fn overlay(a: Color, b: Color) -> Color {
        return vec4<f32>(sq_overlay(a.rgb, b.rgb), a.a);
    }
}

shader! {
    pub fn masked(uv: FragUv, mask: Sampler2D) -> Color {
        let m = textureSample(mask, mask_sampler, uv);
        let edge = sq_smoothstep(0.0, 1.0, m.a);
        return vec4<f32>(m.rgb, m.a * edge);
    }
}

fn check(name: &str, wgsl: &str) {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden");
    let path = dir.join(format!("{name}.wgsl"));
    if std::env::var_os("UPDATE_GOLDEN").is_some() {
        std::fs::create_dir_all(&dir).expect("create golden directory");
        std::fs::write(&path, wgsl).expect("write golden file");
        return;
    }
    let expected = std::fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!(
            "missing golden file {}: {error}\nrun `UPDATE_GOLDEN=1 cargo test -p sequoia-shader --lib golden`",
            path.display()
        )
    });
    assert_eq!(wgsl, expected, "golden mismatch for `{name}`");
}

#[test]
fn solid_golden() {
    check("solid", Solid::WGSL);
}

#[test]
fn gradient_golden() {
    check("gradient", Gradient::WGSL);
}

#[test]
fn hue_shift_golden() {
    check("hue_shift", HueShift::WGSL);
}

#[test]
fn luminance_golden() {
    check("luminance", Luminance::WGSL);
}

#[test]
fn overlay_golden() {
    check("overlay", Overlay::WGSL);
}

#[test]
fn masked_golden() {
    check("masked", Masked::WGSL);
}

#[test]
fn stdlib_helpers_are_available_to_shaders() {
    assert!(HueShift::WGSL.contains("fn sq_rgb_to_hsv"));
    assert!(Overlay::WGSL.contains("fn sq_overlay"));
    assert!(Masked::WGSL.contains("fn sq_smoothstep"));
}

#[test]
fn cpu_stdlib_matches_wgsl_expectations() {
    let hsv = crate::stdlib::rgb_to_hsv(Vec3::new(1.0, 0.0, 0.0));
    assert!((hsv.x - 0.0).abs() < 1e-5);
    assert!((hsv.y - 1.0).abs() < 1e-5);
    assert!((hsv.z - 1.0).abs() < 1e-5);
    let rgb = crate::stdlib::hsv_to_rgb(hsv);
    assert!((rgb.x - 1.0).abs() < 1e-5);
    assert!((rgb.y - 0.0).abs() < 1e-5);
    let hsl = crate::stdlib::rgb_to_hsl(Vec3::new(0.0, 0.0, 1.0));
    let back = crate::stdlib::hsl_to_rgb(hsl);
    assert!((back.z - 1.0).abs() < 1e-5, "{back:?}");
    assert_eq!(
        crate::stdlib::overlay(Vec3::new(0.0, 0.0, 0.0), Vec3::splat(1.0)),
        Vec3::new(0.0, 0.0, 0.0)
    );
    assert_eq!(
        crate::stdlib::soft_light(Vec3::splat(1.0), Vec3::splat(1.0)),
        Vec3::splat(1.0)
    );
    assert_eq!(crate::stdlib::multiply(Vec3::splat(0.5), Vec3::splat(0.5)), Vec3::splat(0.25));
    assert_eq!(crate::stdlib::screen(Vec3::splat(0.5), Vec3::splat(0.5)), Vec3::splat(0.75));
}
